def source(id,title,url,type,supports,limits,**extra):
    entry=dict(id=id,title=title,url=url,type=type,checked_at='2026-10-22',supports=supports,limits=limits,**extra)
    if any(s['id']==id for s in sources):raise ValueError(id)
    sources.append(entry)

source('A15','W3C APG: Grid pattern','https://www.w3.org/WAI/ARIA/apg/patterns/grid/','Primaire informatieve toegankelijkheidspatronen','Verschil tussen gridnavigatie en bediening binnen een cel; beheerde focus.','Webpatroon, geen native implementatiegarantie of vervanging voor gebruikerstests.')
source('A16','W3C APG: Table pattern','https://www.w3.org/WAI/ARIA/apg/patterns/table/','Primaire informatieve toegankelijkheidspatronen','Statische tabel versus interactief grid; voorkeur voor passende HTML-semantiek.','Een leestabel mag losse interactieve onderdelen bevatten; niet ieder interactief tabelonderdeel vereist een volledig grid.')
source('A17','W3C APG: Treegrid pattern','https://www.w3.org/WAI/ARIA/apg/patterns/treegrid/','Primaire informatieve toegankelijkheidspatronen','Hiërarchische interactieve tabel en onderscheid tussen focus en meervoudige selectie.','Voorbeeldpatroon, geen bewijs dat alle BIM-bomen als treegrid moeten worden gebouwd.')
source('A18','Carbon: Data table guidelines','https://www.carbondesignsystem.com/building-blocks/core/components/data-table/guidelines','Primaire leveranciersrichtlijn','Zichtbare batchacties; expliciete grens tussen standaard datatable en spreadsheet.','Ontwerpkeuzes voor Carbon, geen vergelijkend onderzoek of verplichte OpenAEC-maten.')
source('A19','AG Grid: Multi-row selection','https://www.ag-grid.com/javascript-data-grid/row-selection-multi-row/','Primaire actuele leveranciersdocumentatie','SelectAll kan alle, gefilterde of paginarijen omvatten; scope moet gekozen worden.','Bewijst beschikbare implementatievarianten; niet welke standaard OpenAEC-gebruikers prefereren.')
source('A20','AG Grid issue 1494: selectAllFiltered','https://github.com/ag-grid/ag-grid/issues/1494','Historische openbare ontwikkelaarservaring','Melder verwachtte in 2017 selectie van uitsluitend gefilterde rijen.','Gesloten melding over oude versies 6/8. Niet als actueel AG Grid- of OpenAEC-defect gebruikt.')
